import java.net.InetAddress;
import java.net.UnknownHostException;
import java.security.Security;

public class ResolveDemo {
    public static void main(String[] args) throws Exception {
        InetAddress lo = InetAddress.getByName("localhost");
        System.out.println(lo + " loopback=" + lo.isLoopbackAddress());
        for (InetAddress a : InetAddress.getAllByName("localhost")) {
            System.out.println("getAllByName: " + a);
        }
        InetAddress literal = InetAddress.getByName("192.0.2.10");
        System.out.println(literal + " is a " + literal.getClass().getSimpleName()
                + " (no lookup)");
        System.out.println("cache.ttl = " + Security.getProperty("networkaddress.cache.ttl"));
        System.out.println("cache.negative.ttl = "
                + Security.getProperty("networkaddress.cache.negative.ttl"));
        try {
            InetAddress.getByName("no-such-host.invalid");
        } catch (UnknownHostException e) {
            System.out.println("UnknownHostException: " + e.getMessage());
        }
    }
}

import java.security.Security;

public class DnsTtl {
    public static void main(String[] args) {
        // Must run before the first name lookup in the JVM.
        // seconds; -1 = forever, 0 = off
        Security.setProperty("networkaddress.cache.ttl", "30");
        Security.setProperty("networkaddress.cache.negative.ttl", "5");
        System.out.println(Security.getProperty("networkaddress.cache.ttl"));
    }
}

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;

public class LocalServer {
    static final String ETAG = "\"v1-a41c\"";

    static void send(HttpExchange ex, int code, String body) throws IOException {
        byte[] b = body.getBytes(StandardCharsets.UTF_8);
        ex.sendResponseHeaders(code, b.length == 0 ? -1 : b.length);   // -1 = no body
        if (b.length > 0) {
            try (OutputStream os = ex.getResponseBody()) {
                os.write(b);
            }
        }
        ex.close();
    }

    public static void main(String[] args) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress("127.0.0.1", 18080), 0);

        s.createContext("/hello", ex -> {                      // echoes the Host header
            ex.getResponseHeaders().add("Content-Type", "text/plain; charset=utf-8");
            send(ex, 200, "Hello, " + ex.getRequestHeaders().getFirst("Host") + "\n");
});

s.createContext("/report", ex -> {                     // validation with an ETag
    String inm = ex.getRequestHeaders().getFirst("If-None-Match");
    ex.getResponseHeaders().add("ETag", ETAG);
    ex.getResponseHeaders().add("Cache-Control", "max-age=60, must-revalidate");
    if (ETAG.equals(inm)) {
        send(ex, 304, "");
        return;
    }
    ex.getResponseHeaders().add("Content-Type", "application/json");
    send(ex, 200, "{\"total\":42}\n");
});

s.createContext("/stream", ex -> {                     // length 0 selects chunked encoding
    ex.getResponseHeaders().add("Content-Type", "text/plain");
    ex.sendResponseHeaders(200, 0);
    try (OutputStream os = ex.getResponseBody()) {
        os.write("first part\n".getBytes());
        os.flush();
        os.write("second part\n".getBytes());
    }
});

s.createContext("/login", ex -> {                      // issues a session cookie
    ex.getResponseHeaders().add("Set-Cookie",
            "SESSION=abc123; Path=/; HttpOnly; SameSite=Lax; Max-Age=3600");
    send(ex, 204, "");
});

s.createContext("/orders", ex -> {                     // POST with an idempotency key
    String key = ex.getRequestHeaders().getFirst("Idempotency-Key");
    String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
    ex.getResponseHeaders().add("Content-Type", "application/json");
    ex.getResponseHeaders().add("Location", "/orders/1001");
    send(ex, 201, "{\"id\":1001,\"echo\":" + body + ",\"key\":\"" + key + "\"}\n");
});

s.createContext("/api", ex -> {                        // CORS for one allowed origin
    String origin = ex.getRequestHeaders().getFirst("Origin");
    if ("https://app.example.com".equals(origin)) {
        ex.getResponseHeaders().add("Access-Control-Allow-Origin", origin);
        ex.getResponseHeaders().add("Vary", "Origin");
    }
    if ("OPTIONS".equals(ex.getRequestMethod())) {
        ex.getResponseHeaders().add("Access-Control-Allow-Methods", "GET, PUT, DELETE");
        ex.getResponseHeaders().add("Access-Control-Allow-Headers",
                "Content-Type, Authorization");
        ex.getResponseHeaders().add("Access-Control-Max-Age", "600");
        send(ex, 204, "");
        return;
    }
    send(ex, 200, "{\"ok\":true}\n");
});

s.createContext("/events", ex -> {                     // Server-Sent Events
    ex.getResponseHeaders().add("Content-Type", "text/event-stream");
    ex.getResponseHeaders().add("Cache-Control", "no-cache");
    ex.sendResponseHeaders(200, 0);
    try (OutputStream os = ex.getResponseBody()) {
        for (int i = 1; i <= 3; i++) {
            String event = "id: " + i + "\nevent: price\n"
                    + "data: {\"sku\":\"A1\",\"v\":" + (100 + i) + "}\n\n";
            os.write(event.getBytes(StandardCharsets.UTF_8));
            os.flush();
            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                return;
            }
        }
    }
});
        s.start();
        System.out.println("listening on 127.0.0.1:18080");
    }
}

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

public class ConditionalGet {
    static HttpRequest.Builder get(String url) {
        return HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(3)).GET();
    }

    public static void main(String[] args) throws Exception {
        HttpClient http = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_1_1)
                .connectTimeout(Duration.ofSeconds(2))
                .build();
        String url = "http://127.0.0.1:18080/report";

        HttpResponse<String> first = http.send(get(url).build(),
                HttpResponse.BodyHandlers.ofString());
        String etag = first.headers().firstValue("etag").orElseThrow();
        System.out.println("1st: " + first.statusCode() + " etag=" + etag
                + " cache-control=" + first.headers().firstValue("cache-control").orElse("-"));
        System.out.println("     body=" + first.body().trim());

        HttpResponse<String> second = http.send(get(url).header("If-None-Match", etag).build(),
                HttpResponse.BodyHandlers.ofString());
        System.out.println("2nd: " + second.statusCode()
                + " body-length=" + second.body().length());
    }
}

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class H2Probe {
    public static void main(String[] args) throws Exception {
        HttpClient client = HttpClient.newHttpClient();          // default preference: HTTP/2
        System.out.println("client preference: " + client.version());
        HttpResponse<String> r = client.send(
                HttpRequest.newBuilder(URI.create("http://127.0.0.1:18080/hello")).build(),
                HttpResponse.BodyHandlers.ofString());
        System.out.println("negotiated: " + r.version() + ", status " + r.statusCode());
    }
}

